export default "/* src/agent-ui/index.css */\n\n/* The :host selector targets the 'websec-agent-container' \n   element from inside the Shadow DOM \n*/\n:host {\n  all: initial; /* Reset all inherited styles from the host website */\n  display: block;\n  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n}\n\n.agent-bubble {\n  width: 50px;\n  height: 50px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, #007bff 0%, #0056b3 100%);\n  color: white;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n  user-select: none;\n  border: 2px solid rgba(255, 255, 255, 0.2);\n}\n\n.agent-bubble:hover {\n  transform: scale(1.05);\n  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);\n}\n\n.agent-bubble.danger {\n  background: linear-gradient(135deg, #ff4d4d 0%, #b30000 100%);\n  animation: pulse 2s infinite;\n}\n\n.dashboard-container {\n  position: absolute;\n  bottom: 70px;\n  right: 0;\n  width: 320px;\n  max-height: 450px;\n  background: #ffffff;\n  border-radius: 16px;\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  border: 1px solid #e1e4e8;\n  animation: slideIn 0.3s ease-out;\n}\n\n.dashboard-header {\n  padding: 16px;\n  background: #f6f8fa;\n  border-bottom: 1px solid #e1e4e8;\n  font-weight: bold;\n  font-size: 14px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.alert-item {\n  padding: 12px;\n  margin: 8px 16px;\n  background: #fff5f5;\n  border-left: 4px solid #ff4d4d;\n  border-radius: 4px;\n  font-size: 13px;\n  color: #c53030;\n  line-height: 1.4;\n}\n\n.status-safe {\n  color: #28a745;\n  font-size: 12px;\n  padding: 16px;\n  text-align: center;\n}\n\n@keyframes pulse {\n  0% { box-shadow: 0 0 0 0 rgba(255, 77, 77, 0.7); }\n  70% { box-shadow: 0 0 0 10px rgba(255, 77, 77, 0); }\n  100% { box-shadow: 0 0 0 0 rgba(255, 77, 77, 0); }\n}\n\n@keyframes slideIn {\n  from { opacity: 0; transform: translateY(20px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n"